CREATE TABLE composiciones_suplementos (id BIGSERIAL PRIMARY KEY,suplemento_catalogo_id BIGINT NOT NULL REFERENCES suplementos_catalogo(id),version INTEGER NOT NULL,cantidad_porcion_referencia NUMERIC(12,4) NOT NULL,unidad_porcion_id BIGINT NOT NULL REFERENCES unidades_medida(id),fecha_desde DATE NOT NULL,fecha_hasta DATE,activo BOOLEAN NOT NULL DEFAULT TRUE,fuente_datos VARCHAR(1000),creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_composicion_suplemento_version UNIQUE(suplemento_catalogo_id,version),CONSTRAINT ck_composicion_suplemento_cantidad CHECK(cantidad_porcion_referencia>0),CONSTRAINT ck_composicion_suplemento_fechas CHECK(fecha_hasta IS NULL OR fecha_hasta>=fecha_desde));
CREATE TABLE componentes_composicion_suplementos (id BIGSERIAL PRIMARY KEY,composicion_suplemento_id BIGINT NOT NULL REFERENCES composiciones_suplementos(id),tipo VARCHAR(30) NOT NULL,nombre_otro VARCHAR(200),cantidad NUMERIC(12,4) NOT NULL,unidad_id BIGINT NOT NULL REFERENCES unidades_medida(id),CONSTRAINT ck_componente_cantidad CHECK(cantidad>=0),CONSTRAINT ck_componente_otro CHECK((tipo='OTRO' AND nombre_otro IS NOT NULL) OR tipo<>'OTRO'));
CREATE TABLE equivalencias_unidades_suplementos (id BIGSERIAL PRIMARY KEY,suplemento_catalogo_id BIGINT NOT NULL REFERENCES suplementos_catalogo(id),version INTEGER NOT NULL,cantidad_origen NUMERIC(12,4) NOT NULL,unidad_origen_id BIGINT NOT NULL REFERENCES unidades_medida(id),cantidad_destino NUMERIC(12,4) NOT NULL,unidad_destino_id BIGINT NOT NULL REFERENCES unidades_medida(id),fecha_desde DATE NOT NULL,fecha_hasta DATE,activo BOOLEAN NOT NULL DEFAULT TRUE,fuente_datos VARCHAR(1000),creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_equivalencia_suplemento_version UNIQUE(suplemento_catalogo_id,version),CONSTRAINT ck_equivalencia_suplemento_cantidad CHECK(cantidad_origen>0 AND cantidad_destino>0),CONSTRAINT ck_equivalencia_suplemento_fechas CHECK(fecha_hasta IS NULL OR fecha_hasta>=fecha_desde));
ALTER TABLE registros_consumo_suplemento ADD COLUMN composicion_suplemento_id BIGINT NULL REFERENCES composiciones_suplementos(id);
ALTER TABLE registros_consumo_suplemento ADD COLUMN equivalencia_unidad_suplemento_id BIGINT NULL REFERENCES equivalencias_unidades_suplementos(id);
CREATE INDEX ix_composicion_suplemento_vigencia ON composiciones_suplementos(suplemento_catalogo_id,activo,fecha_desde,fecha_hasta,version);
CREATE INDEX ix_consumo_suplemento_composicion ON registros_consumo_suplemento(composicion_suplemento_id);
